package game.agent.eval;

import game.agent.growth.*;import game.agent.llm.*;import game.agent.runtime.*;import game.agent.action.ActionResult;import game.agent.tools.ToolRequest;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;import java.nio.file.*;import java.nio.charset.StandardCharsets;

/** V4 first evaluation slice: isolated forest Lv.5->6 cases and complete bounded traces. */
public final class GrowthBatchEvaluation {
 private GrowthBatchEvaluation(){}
 public static AgentLoop.DecisionProvider scripted(){return context->{Map<String,String> observation=context.getObservation();String phase=observation.get("trainingPhase"),region=observation.get("region");if("REST".equals(phase))return choice("rest",Collections.emptyMap());if("RETURN_TO_REST".equals(phase))return choice("go_to_recovery",Collections.emptyMap());if("PREPARE_NEW_EXPEDITION".equals(phase))return choice("next_expedition",Collections.emptyMap());if("RETURN_FOR_NEW_EXPEDITION".equals(phase))return choice("go_to_region",Json.object("regionId","lab"));if(!"forest".equals(region))return choice("go_to_region",Json.object("regionId","forest"));List<Object> rows=Json.asArray(Json.read(observation.get("encounters")));if(rows.isEmpty())return choice("go_to_region",Json.object("regionId","lab"));Map<String,Object> target=Json.asObject(rows.get(0));if(!Boolean.TRUE.equals(target.get("targetAdjacent")))return choice("move_to",Json.object("targetId",target.get("id")));return choice("use_skill",Json.object("targetId",target.get("id"),"moveId",target.get("recommendedMoveId")));};}
 private static ToolRequest choice(String tool,Map<String,Object> arguments){return new ToolRequest("scripted-choice",tool,arguments);}
 private static final class Meter implements AgentLoop.DecisionProvider {
  private final AgentLoop.DecisionProvider provider;private final List<Map<String,Object>> calls=new ArrayList<>();private final AtomicLong issued=new AtomicLong();private final ThreadLocal<Map<String,Number>> usage=ThreadLocal.withInitial(Collections::emptyMap);
  Meter(AgentLoop.DecisionProvider provider){this.provider=Objects.requireNonNull(provider);}
  public ToolRequest decide(AgentLoop.Context context){long call=issued.incrementAndGet(),start=System.nanoTime();boolean ok=false;usage.remove();try{ToolRequest result=provider.decide(context);ok=true;return result;}finally{Map<String,Number> actual=new LinkedHashMap<>();try{for(Map.Entry<String,Number> e:provider.getUsage().entrySet())if(Arrays.asList("inputTokens","outputTokens","totalTokens").contains(e.getKey())&&e.getValue()!=null&&Double.isFinite(e.getValue().doubleValue())&&e.getValue().doubleValue()==e.getValue().longValue()&&e.getValue().longValue()>=0&&e.getValue().longValue()<=1000000000L)actual.put(e.getKey(),e.getValue().longValue());}catch(RuntimeException ignored){}usage.set(Collections.unmodifiableMap(actual));synchronized(calls){calls.add(Json.object("callIndex",call,"success",ok,"latencyMs",(System.nanoTime()-start)/1000000.0,"usage",actual));}}}
  public Map<String,Number> getUsage(){return usage.get();}
  List<Map<String,Object>> snapshot(){synchronized(calls){return new ArrayList<>(calls);}}
 }
 public static Map<String,Object> run(long seed,String starter,AgentLoop.DecisionProvider provider,String providerName,String model,int timeoutMillis,long wallLimitMillis)throws InterruptedException {
  if(timeoutMillis<1||timeoutMillis>61000||wallLimitMillis<1||wallLimitMillis>600000)throw new IllegalArgumentException("INVALID_EVAL_LIMIT");
  GrowthWorld world=SeededGrowthFixture.reset(seed,starter);Map<String,Object> initial=world.export();Meter meter=new Meter(provider);ExecutorService executor=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"growth-evaluation-provider");t.setDaemon(true);return t;});
  AgentTask task=new AgentTask("growth-eval-"+Long.toHexString(seed));task.start();AgentLoop loop=new AgentLoop(task,"Train selected individual "+world.partner().captureId+" from Lv.5 to at least Lv.6 in forest through native use_skill. Use real navigation, camp recovery when HP/PP is low, and return lab then next_expedition only when needed. Do not capture, evolve or change partners.",world.trainingTools("forest"),executor,meter,world::observation,()->world.partner().level()>=6&&"forest".equals(world.region()),timeoutMillis,100,100,8);loop.configureTrace(world.partner().captureId,providerName,model);
  List<Object> trace=new ArrayList<>();long lastSequence=0,start=System.nanoTime();String terminal="";
  try{while(true){long now=System.nanoTime()/1000000;ActionResult event=loop.tick(now);for(Map<String,Object> row:loop.getStepTrace()){long sequence=((Number)row.get("stepNumber")).longValue();if(sequence>lastSequence){Map<String,Object> copy=new LinkedHashMap<>(row);copy.put("providerCallIndex",meter.issued.get());trace.add(copy);lastSequence=sequence;}}AgentTask.State state=loop.getState();if(Arrays.asList(AgentTask.State.COMPLETED,AgentTask.State.FAILED,AgentTask.State.PROVIDER_UNAVAILABLE,AgentTask.State.CANCELLED).contains(state)){terminal=state.name();break;}if((System.nanoTime()-start)/1000000>=wallLimitMillis){terminal="WALL_TIME_LIMIT";loop.cancel();break;}if("DECISION_PENDING".equals(event.getCode()))Thread.sleep(5);}}
  finally{if(!Arrays.asList(AgentTask.State.COMPLETED,AgentTask.State.FAILED,AgentTask.State.CANCELLED).contains(loop.getState()))loop.cancel();executor.shutdownNow();executor.awaitTermination(Math.min(timeoutMillis,1000),TimeUnit.MILLISECONDS);}
  List<Map<String,Object>> calls=meter.snapshot();Map<String,Object> metrics=metrics(trace,calls,terminal,world.turn());metrics.put("providerCallsIssued",meter.issued.get());metrics.put("outstandingProviderCalls",Math.max(0,meter.issued.get()-calls.size()));if(meter.issued.get()!=calls.size()){metrics.put("usageComplete",false);metrics.put("inputTokens",null);metrics.put("outputTokens",null);metrics.put("totalTokens",null);}Map<String,Object> checkpoint=world.export();return Json.object("seed",seed,"starter",starter,"scenario","forest-native-level5-to6-v1","rulesVersion","v3-expansion-demo-20261003","initialWorld",initial,"initialFingerprint",SeededGrowthFixture.fingerprint(initial),"terminal",terminal,"completed","COMPLETED".equals(terminal),"elapsedMs",(System.nanoTime()-start)/1000000.0,"metrics",metrics,"providerCalls",calls,"trace",trace,"finalWorld",checkpoint,"finalFingerprint",SeededGrowthFixture.fingerprint(checkpoint));
 }
 /** Usage counts each actual provider call once, never repeated IN_PROGRESS trace rows. */
 public static Map<String,Object> metrics(List<Object> trace,List<Map<String,Object>> calls,String terminal,int turns){long steps=0,invalid=0,recoveries=0,failures=0,input=0,output=0,total=0,withUsage=0;double latency=0;for(Object value:trace){Map<String,Object> row=Json.asObject(value);if(row.get("toolName")!=null){steps++;if("REJECTED".equals(row.get("actionStatus")))invalid++;if("rest".equals(row.get("toolName"))&&"SUCCESS".equals(row.get("actionStatus")))recoveries++;}if(Arrays.asList("FAILED","TIMED_OUT").contains(row.get("actionStatus")))failures++;}for(Map<String,Object> call:calls){latency+=((Number)call.get("latencyMs")).doubleValue();Map<String,Object> usage=Json.asObject(call.get("usage"));if(usage.containsKey("inputTokens")&&usage.containsKey("outputTokens")&&usage.containsKey("totalTokens")){withUsage++;input+=((Number)usage.get("inputTokens")).longValue();output+=((Number)usage.get("outputTokens")).longValue();total+=((Number)usage.get("totalTokens")).longValue();}}boolean completeUsage=!calls.isEmpty()&&withUsage==calls.size();return Json.object("completed","COMPLETED".equals(terminal),"actionSteps",steps,"worldTurns",turns,"invalidActions",invalid,"invalidActionRate",steps==0?0.0:invalid/(double)steps,"successfulRestActions",recoveries,"failureEvents",failures,"providerCalls",calls.size(),"averageProviderLatencyMs",calls.isEmpty()?null:latency/calls.size(),"usageComplete",completeUsage,"usageCallsAvailable",withUsage,"inputTokens",completeUsage?input:null,"outputTokens",completeUsage?output:null,"totalTokens",completeUsage?total:null,"observedInputTokens",withUsage==0?null:input,"observedOutputTokens",withUsage==0?null:output,"cost",null,"costReason","PRICE_NOT_CONFIGURED","recoverySuccessRate",null,"recoveryRateReason","FAULT_SCENARIOS_NOT_IMPLEMENTED");}
 public static Map<String,Object> batch(List<Map<String,Object>> runs,String provider,String model){if(runs.isEmpty()||runs.size()>10)throw new IllegalArgumentException("INVALID_BATCH_SIZE");Set<String> seeds=new HashSet<>();long steps=0,invalid=0,completed=0;for(Map<String,Object> run:runs){if(!seeds.add(run.get("seed")+":"+run.get("starter")))throw new IllegalArgumentException("DUPLICATE_EVAL_CASE");Map<String,Object> metrics=Json.asObject(run.get("metrics"));steps+=((Number)metrics.get("actionSteps")).longValue();invalid+=((Number)metrics.get("invalidActions")).longValue();if(Boolean.TRUE.equals(run.get("completed")))completed++;}return Json.object("schemaVersion",1,"kind","V4_GROWTH_EVALUATION_FOUNDATION","status",completed==runs.size()?"PASSED":"COMPLETED_WITH_FAILURES","provider",provider,"model",model,"realAi","openai".equals(provider),"cases",runs.size(),"completedCases",completed,"completionRate",completed/(double)runs.size(),"averageActionSteps",steps/(double)runs.size(),"invalidActionRate",steps==0?0.0:invalid/(double)steps,"cost",null,"scope","Fixed seed/reset fixtures and one forest training scenario. Model outputs may vary. Not the full V4 platform.","runs",runs);}
 public static void main(String[] args)throws Exception{if(args.length<3||args.length>4||!Arrays.asList("live","scripted").contains(args[0]))throw new IllegalArgumentException("Usage: GrowthBatchEvaluation live|scripted report.json seedCSV [TREECKO|MUDKIP|TORCHIC]");String[] values=args[2].split(",");if(values.length<1||values.length>10)throw new IllegalArgumentException("Batch limit 10");List<Long> seeds=new ArrayList<>();for(String value:values){long seed=Long.parseLong(value);if(seeds.contains(seed))throw new IllegalArgumentException("Duplicate seed");seeds.add(seed);}String starter=args.length==4?args[3]:"TREECKO";if(!GrowthRules.starter(starter))throw new IllegalArgumentException("Invalid starter");boolean live=args[0].equals("live");OpenAiConfig config=live?OpenAiConfig.fromEnvironment(System.getenv()):null;String provider=live?"openai":"scripted",model=live?config.getModel():"damage-baseline-v1";List<Map<String,Object>> runs=new ArrayList<>();for(long seed:seeds){AgentLoop.DecisionProvider gateway=live?new OpenAiGateway(config,new OpenAiHttpTransport()):scripted();Map<String,Object> run=run(seed,starter,gateway,provider,model,live?config.getTimeoutMillis()+1000:1000,live?180000:10000);runs.add(run);Files.write(Paths.get(args[1]),Json.write(batch(runs,provider,model)).getBytes(StandardCharsets.UTF_8));System.out.println("Seed "+seed+": "+run.get("terminal")+", action steps "+Json.asObject(run.get("metrics")).get("actionSteps"));}if(!"PASSED".equals(batch(runs,provider,model).get("status")))System.exit(1);}
}


